-- Migrate WBS status values: PLANNED -> NOT_STARTED, IN_PROGRESS -> IN_DEVELOPMENT
UPDATE pm_wbs_element SET STATUS = 'NOT_STARTED' WHERE STATUS = 'PLANNED' AND DEL_FLAG = '0';
UPDATE pm_wbs_element SET STATUS = 'IN_DEVELOPMENT' WHERE STATUS = 'IN_PROGRESS' AND DEL_FLAG = '0';

